import{_ as t,o as a,c as n,a2 as o}from"./chunks/framework.CDEKL17z.js";const p=JSON.parse('{"title":"The admin UI","description":"","frontmatter":{},"headers":[],"relativePath":"guide/admin.md","filePath":"guide/admin.md"}'),s={name:"guide/admin.md"};function r(i,e,l,d,c,h){return a(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="the-admin-ui" tabindex="-1">The admin UI <a class="header-anchor" href="#the-admin-ui" aria-label="Permalink to &quot;The admin UI&quot;">​</a></h1><p><code>/admin</code>, protected by <code>MICHI_ADMIN_PASSWORD</code>. This is the single-operator control panel: every bot on the platform is configured here, and nowhere else.</p><h2 id="creating-a-tenant" tabindex="-1">Creating a tenant <a class="header-anchor" href="#creating-a-tenant" aria-label="Permalink to &quot;Creating a tenant&quot;">​</a></h2><p><strong>Admin → New tenant.</strong> A tenant is one business: a slug (immutable, it forms the chat URL <code>/t/&lt;slug&gt;</code>), a name, and a starter persona. A public embed key is minted automatically - a tenant with no key cannot be visited.</p><h2 id="the-tenant-form" tabindex="-1">The tenant form <a class="header-anchor" href="#the-tenant-form" aria-label="Permalink to &quot;The tenant form&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Section</th><th>What it controls</th></tr></thead><tbody><tr><td>Identity</td><td>Name, active/disabled, model alias override, <strong>timezone</strong> (cap reset + analytics buckets), <strong>daily message cap</strong>, store-conversations switch</td></tr><tr><td>Persona</td><td>The tenant layer of the system prompt: identity, hours, location, voice. The bot replies in the visitor&#39;s language automatically</td></tr><tr><td>Protection rules</td><td>Hard boundaries in your words (e.g. &quot;never quote rental prices&quot;, &quot;only answer about the cafe, no stories&quot;). Can only tighten behaviour, never loosen the platform rules</td></tr><tr><td>Branding</td><td>Title, greeting, subtitle, composer placeholder, accent color, suggestion chips</td></tr><tr><td>Tools</td><td>Enable tool packs and fill in their parameters (see below)</td></tr><tr><td>Notifications</td><td>Optional Slack incoming webhook - new-conversation and cap-reached alerts</td></tr><tr><td>Allowed origins</td><td>Which websites may embed this bot (one origin per line)</td></tr></tbody></table><p>Three fields deserve a note:</p><ul><li><strong>Daily message cap</strong> is the control that actually protects your bill. The embed key is public by design, so assume anyone can call the API; the cap is what bounds the damage.</li><li><strong>Persona</strong> is wrapped in delimiters below a fixed platform preamble it cannot override. Keep it to identity and voice; live facts belong in tools and the knowledge base.</li><li><strong>Slack webhook</strong> must be exactly a <code>https://hooks.slack.com/services/…</code> URL. Nothing else is accepted - that restriction is a security boundary, not a bug.</li></ul><h2 id="tools" tabindex="-1">Tools <a class="header-anchor" href="#tools" aria-label="Permalink to &quot;Tools&quot;">​</a></h2><p>Tools are <strong>code packs</strong>: the platform owns the code, a tenant enables a pack and fills in parameters (like a site base URL). Tenants never supply raw URLs. Enable <code>search_kb</code> to give the bot access to the tenant&#39;s <a href="./knowledge-base">knowledge base</a>.</p><h2 id="keys" tabindex="-1">Keys <a class="header-anchor" href="#keys" aria-label="Permalink to &quot;Keys&quot;">​</a></h2><p><strong>Tenant → Embed keys.</strong> Public keys ship in a customer&#39;s page source, so they&#39;re shown in full - they select a tenant, they don&#39;t authorize anything. Rotation: create a new key, deploy it, revoke the old one (revoked keys stay visible so stray traffic can be noticed).</p><h2 id="conversations-usage-analytics" tabindex="-1">Conversations, usage, analytics <a class="header-anchor" href="#conversations-usage-analytics" aria-label="Permalink to &quot;Conversations, usage, analytics&quot;">​</a></h2><p><strong>Admin → Conversations</strong> shows every transcript (rendered as plain text deliberately); owners can export any transcript as JSON or delete it outright. <strong>Admin → Usage</strong> aggregates messages, tokens and latency per tenant per day. <strong>Tenant → Analytics</strong> breaks down the last 30 days: volume, tool mix, the actual knowledge-base queries visitors triggered, busy hours, origins, and (behind Cloudflare) country-level location - never IPs.</p><h2 id="moving-a-tenant-between-instances" tabindex="-1">Moving a tenant between instances <a class="header-anchor" href="#moving-a-tenant-between-instances" aria-label="Permalink to &quot;Moving a tenant between instances&quot;">​</a></h2><p><strong>Tenant → Export JSON</strong> (owner only) downloads everything that makes the tenant: settings, branding, tools, origins, and the knowledge base. <strong>Admin → Import a tenant</strong> brings it to any michi-chat instance - laptop to production in one file. Imports into an existing tenant show a preview of exactly what would change and require an explicit overwrite confirmation; knowledge is re-embedded on arrival, so transfers work across different embedding models.</p><h2 id="roles-and-privacy" tabindex="-1">Roles and privacy <a class="header-anchor" href="#roles-and-privacy" aria-label="Permalink to &quot;Roles and privacy&quot;">​</a></h2><p><strong>Accounts</strong> (owner only) adds staff logins: conversations/usage reading plus knowledge-base editing, nothing else. The env <code>ADMIN_PASSWORD</code> stays a break-glass owner login. Each tenant also has a <strong>Store conversations</strong> switch - off means nothing is written to the database at all, at the cost of multi-turn memory (the daily cap still applies via a separate counter).</p>',18)])])}const u=t(s,[["render",r]]);export{p as __pageData,u as default};
